input.command:
sqlite3 "/data/arabic_dict.db" "
SELECT e.id, e.headword, e.headword_norm, substr(e.definitions_text,1,500) as def
FROM entries e
WHERE e.dictionary_id IN (4,151) AND (e.headword_norm LIKE 'عدم%')
ORDER BY e.headword_norm LIMIT 5;

SELECT '---MAQAYIS_SHARA---';

SELECT e.id, e.headword, substr(e.definitions_text,1,500) as def
FROM entries e
WHERE e.dictionary_id IN (4,151) AND e.headword_norm = 'شرع' LIMIT 2;

SELECT '---LAASHARIA ENTRY---';
SELECT e.id, e.headword, e.headword_norm, e.root, d.name_ar, e.definitions_text
FROM entries e JOIN dictionaries d ON e.dictionary_id = d.id
WHERE e.id = 51122;
" 2>&1 | head -60
